import { describe, expect, it } from 'vitest';
import { activateCard, createGame } from '../state.ts';
import { createActiveClock } from './clock.ts';

function mismatch() {
  const game = createGame('np1-4-1');
  if (game === null) throw new Error('Invalid test deal.');
  return activateCard(activateCard(game, 0), 1);
}

describe('active session time', () => {
  it('accounts for fractional active time through hidden and resumed intervals', () => {
    const clock = createActiveClock(0, true);
    let game = clock.setVisible(mismatch(), false, 250.5, false);
    expect(game.elapsedMs).toBe(250.5);
    game = clock.advance(game, false, 5000);
    game = clock.setVisible(game, false, 6000, true);
    expect(game.elapsedMs).toBe(250.5);
    game = clock.advance(game, false, 6549.25);
    expect(game.selection).toEqual({ kind: 'mismatch', first: 0, second: 1, remainingMs: 0.25 });
    game = clock.advance(game, false, 6549.5);
    expect(game.selection).toEqual({ kind: 'closed' });
    expect(game.elapsedMs).toBe(800);
  });

  it('discards paused import time and starts from the remaining interval on resume', () => {
    const clock = createActiveClock(0, true);
    let game = clock.advance(mismatch(), true, 5000);
    expect(game.elapsedMs).toBe(0);
    clock.reset(7000, true);
    game = clock.advance(game, false, 7799);
    expect(game.selection.kind).toBe('mismatch');
    game = clock.advance(game, false, 7800);
    expect(game.selection.kind).toBe('closed');
    expect(game.elapsedMs).toBe(800);
  });

  it('reset anchors a new deal without carrying the previous deal time', () => {
    const clock = createActiveClock(0, true);
    clock.advance(mismatch(), false, 799);
    clock.reset(799, true);
    const next = clock.advance(mismatch(), false, 800);
    expect(next.elapsedMs).toBe(1);
    expect(next.selection).toEqual({ kind: 'mismatch', first: 0, second: 1, remainingMs: 799 });
  });
});
import { afterEach, describe, expect, it, vi } from 'vitest';
import { bestKey, browserStorage, readPreferences, saveBest, saveSize, SIZE_KEY } from './storage.ts';
import type { SessionStorage } from './storage.ts';

function memoryStorage(entries: readonly (readonly [string, string])[] = []) {
  const values = new Map(entries);
  const storage: SessionStorage = {
    getItem: (key) => values.get(key) ?? null,
    setItem: (key, value) => { values.set(key, value); },
  };
  return { storage, values };
}

afterEach(() => vi.unstubAllGlobals());

describe('saved preferences', () => {
  it('restores a supported size and bounded whole bests independently', () => {
    const { storage } = memoryStorage([
      [SIZE_KEY, '16'], [bestKey(4), '0'], [bestKey(6), '999999'],
      [bestKey(8), '1000000'], [bestKey(10), '1.5'], [bestKey(12), '-1'], [bestKey(14), '"4"'],
    ]);
    expect(readPreferences(storage)).toEqual({ size: 16, bests: { 4: 0, 6: 999999 } });
  });

  it.each(['5', 'null', '"8"', '{}', '[4]', '{', 'Infinity'])('ignores invalid saved size %s', (text) => {
    const { storage } = memoryStorage([[SIZE_KEY, text], [bestKey(4), '8']]);
    expect(readPreferences(storage)).toEqual({ size: 4, bests: { 4: 8 } });
  });

  it.each(['null', 'NaN', '1e400', '{}', 'true', '9007199254740992'])('ignores invalid saved best %s', (text) => {
    const { storage } = memoryStorage([[bestKey(4), text]]);
    expect(readPreferences(storage).bests).toEqual({});
  });

  it('writes only its own keys and preserves unrelated storage', () => {
    const { storage, values } = memoryStorage([['other-app', 'keep']]);
    saveSize(storage, 12);
    saveBest(storage, 12, 73);
    expect([...values]).toEqual([['other-app', 'keep'], [SIZE_KEY, '12'], [bestKey(12), '73']]);
  });

  it('survives getter, read and write failures', () => {
    vi.stubGlobal('window', { get localStorage() { throw new Error('Blocked'); } });
    expect(browserStorage()).toBeNull();
    const storage: SessionStorage = {
      getItem: () => { throw new Error('Blocked'); },
      setItem: () => { throw new Error('Full'); },
    };
    expect(readPreferences(storage)).toEqual({ size: 4, bests: {} });
    expect(() => { saveSize(storage, 4); saveBest(storage, 4, 8); }).not.toThrow();
    expect(readPreferences(null)).toEqual({ size: 4, bests: {} });
    expect(() => { saveSize(null, 4); saveBest(null, 4, 8); }).not.toThrow();
  });
});
import { describe, expect, it } from 'vitest';
import { activateCard, createGame } from '../state.ts';
import { announce, turnResult } from './announcements.ts';

function initial() {
  const game = createGame('np1-4-1');
  if (game === null) throw new Error('Invalid test deal.');
  return game;
}

describe('turn announcements', () => {
  it('announces a second reveal and ignores first/repeated reveals', () => {
    const hidden = initial();
    const one = activateCard(hidden, 0);
    expect(turnResult(hidden, one)).toBeNull();
    expect(turnResult(one, activateCard(one, 0))).toBeNull();
    expect(turnResult(one, activateCard(one, 1))).toBe('No match. Cards close after a short pause.');
    const matched = activateCard(one, 11);
    expect(turnResult(one, matched)).toBe('Pair found. 1 pair matched.');
    const next = activateCard(matched, 1);
    expect(turnResult(next, activateCard(next, 9))).toBe('Pair found. 2 pairs matched.');
  });

  it('gives identical consecutive results distinct event identities', () => {
    const first = announce({ id: 0, text: '' }, 'No match. Cards close after a short pause.');
    const second = announce(first, first.text);
    expect(second.text).toBe(first.text);
    expect(second.id).toBe(first.id + 1);
  });

  it('combines the last match and win into one announcement', () => {
    let game = initial();
    let message: string | null = null;
    for (let face = 0; face < 8; face += 1) {
      const one = activateCard(game, game.board.deck.indexOf(face));
      game = activateCard(one, game.board.deck.lastIndexOf(face));
      message = turnResult(one, game);
    }
    expect(message).toBe('Pair found. All pairs found in 8 moves and 0:00.');
  });
});

