import { faceIdentity } from './faceIdentity.ts';
import { Shape } from './Shape.tsx';

export function Face({ id }: Readonly<{ id: number }>) {
  const face = faceIdentity(id);
  const outlined = face.fill === 'outline';
  return (
    <svg className="card-face" viewBox="0 0 100 100" aria-hidden="true" focusable="false">
      <g fill={outlined ? 'none' : face.color} stroke={outlined ? face.color : 'none'}
        strokeWidth={outlined ? 5 : 0} strokeLinejoin="round">
        <Shape shape={face.shape} />
      </g>
      <circle cx={face.marker.x} cy={face.marker.y} r="5" fill={face.color}
        stroke="#111625" strokeWidth="3" />
    </svg>
  );
}
import type { FaceShape } from './faceIdentity.ts';

export function Shape({ shape }: Readonly<{ shape: FaceShape }>) {
  switch (shape) {
    case 'circle': return <circle cx="50" cy="50" r="25" />;
    case 'square': return <rect x="25" y="25" width="50" height="50" />;
    case 'triangle': return <polygon points="50,25 75,75 25,75" />;
    case 'diamond': return <polygon points="50,25 75,50 50,75 25,50" />;
    case 'star': return <polygon points="50,25 58,41 75,44 62,56 66,75 50,65 34,75 38,56 25,44 42,41" />;
    case 'hexagon': return <polygon points="50,25 75,37.5 75,62.5 50,75 25,62.5 25,37.5" />;
    case 'plus': return <path d="M42 25H58V42H75V58H58V75H42V58H25V42H42Z" />;
    case 'chevron': return <polygon points="25,25 50,42 75,25 75,50 50,75 25,50" />;
  }
}
const SHAPES = ['circle', 'square', 'triangle', 'diamond', 'star', 'hexagon', 'plus', 'chevron'] as const;
const diagonal = Math.SQRT1_2;
const MARKERS = [
  { name: 'top', x: 0, y: -1 }, { name: 'top-right', x: diagonal, y: -diagonal },
  { name: 'right', x: 1, y: 0 }, { name: 'bottom-right', x: diagonal, y: diagonal },
  { name: 'bottom', x: 0, y: 1 }, { name: 'bottom-left', x: -diagonal, y: diagonal },
  { name: 'left', x: -1, y: 0 }, { name: 'top-left', x: -diagonal, y: -diagonal },
] as const;
const PALETTE = [
  { name: 'cyan', hex: '#63E7FF' }, { name: 'magenta', hex: '#FF71D6' },
  { name: 'green', hex: '#8BEA7D' }, { name: 'yellow', hex: '#FFE082' },
  { name: 'orange', hex: '#FFB064' }, { name: 'violet', hex: '#B49AFF' },
  { name: 'rose', hex: '#FF8296' }, { name: 'ice', hex: '#D9F3FF' },
] as const;

export type FaceShape = (typeof SHAPES)[number];

export function faceIdentity(id: number) {
  const shape = SHAPES[id % 8];
  const markerIndex = Math.floor(id / 8) % 8;
  const marker = MARKERS[markerIndex];
  const color = PALETTE[markerIndex];
  if (!Number.isInteger(id) || id < 0 || id > 127 || shape === undefined
    || marker === undefined || color === undefined) throw new Error('Invalid face identity.');
  const fill = id < 64 ? 'solid' : 'outline';
  return { shape, fill, color: color.hex,
    marker: { x: 50 + marker.x * 40, y: 50 + marker.y * 40 },
    name: `${color.name} ${fill} ${shape}, marker ${marker.name}` };
}
