  await page.keyboard.press('Enter');
  await expect(stat(page, 'Moves')).toHaveText('Moves: 1');
  await expect(cards(page).nth(0)).toHaveAttribute('aria-disabled', 'true');
  await expect(cards(page).nth(0)).toBeFocused();
});

