import { expect, test } from '@playwright/test';
import { cards, loadBoard, openGame } from './support.ts';

test.use({ hasTouch: true });
for (const width of [360, 1280]) {
  test(`touch scrolling reaches both ends of the 16x16 board at width ${width}`, async ({ page, context }) => {
    await page.setViewportSize({ width, height: 800 });
    await openGame(page);
    await loadBoard(page, 'np1-16-1');
    const area = page.locator('.board-scroll');
    await area.scrollIntoViewIfNeeded();
    const rect = await area.boundingBox();
    if (rect === null) throw new Error('Missing scroll area.');
    const session = await context.newCDPSession(page);
    const gesture = async (distance: number) => session.send('Input.synthesizeScrollGesture', {
      x: rect.x + rect.width / 2, y: rect.y + rect.height / 2,
      xDistance: width === 360 ? distance : 0, yDistance: distance,
      speed: 4000, gestureSourceType: 'touch', preventFling: true,
    });
    await gesture(-2000);
    await expect(cards(page).last()).toBeInViewport();
    await gesture(2000);
    await expect(cards(page).first()).toBeInViewport();
    expect(await page.evaluate(() => document.documentElement.scrollWidth === innerWidth)).toBe(true);
    await session.detach();
  });
}

